package com.hifleet.analysis.portcall.model;

/**
 * Cleaned AIS point generated by preprocessing stage.
 */
public class CleanAisPoint extends AisPoint {

    private static final long serialVersionUID = 1L;

    private boolean duplicate;
    private boolean jumpPoint;
    private long reorderLagSeconds;
    private String qualityNote;

    /**
     * Marks this point as accepted by all current preprocess checks.
     *
     * @return true when point can enter downstream state machine
     */
    public boolean isUsable() {
        return !duplicate && !jumpPoint;
    }

    public boolean isDuplicate() {
        return duplicate;
    }

    public void setDuplicate(boolean duplicate) {
        this.duplicate = duplicate;
    }

    public boolean isJumpPoint() {
        return jumpPoint;
    }

    public void setJumpPoint(boolean jumpPoint) {
        this.jumpPoint = jumpPoint;
    }

    public long getReorderLagSeconds() {
        return reorderLagSeconds;
    }

    public void setReorderLagSeconds(long reorderLagSeconds) {
        this.reorderLagSeconds = reorderLagSeconds;
    }

    public String getQualityNote() {
        return qualityNote;
    }

    public void setQualityNote(String qualityNote) {
        this.qualityNote = qualityNote;
    }
}
